function singletonPiece(piece: Piece, sourceIndex: number): Piece {
	return piece.kind === "base"
		? { kind: "base", start: sourceIndex, length: 1, step: 1 }
		: { kind: "insert", source: piece.source, start: sourceIndex, length: 1, step: 1 };
}

