async function disposeFacetRecords(records: readonly FacetRuntime[]): Promise<unknown[]> {
	const errors: unknown[] = [];
	for (const record of records) {
		try {
			await record.lifecycle.dispose();
		} catch (error) {
			errors.push(error);
		}
	}
	return errors;
}

