			const storedPackagePaths = await readSessionPluginPackageProfile(directory, serverId, metadata.path);
			const selected =
				storedPackagePaths === undefined ? defaultPluginSelection : await buildPluginSelection(storedPackagePaths);
			if (storedPackagePaths === undefined) {
				await writeSessionPluginPackageProfile(directory, serverId, metadata.path, selected.packagePaths);
			}
			sessionPluginSelections.set(metadata.path, selected);
			return selected;
		};
		const removeSessionPlugins = async (metadata: SessionCatalogMetadata): Promise<void> => {
			sessionPluginSelections.delete(metadata.path);
			await removeSessionPluginPackageProfile(directory, serverId, metadata.path);
		};
		const reloadPresentationFacetBundles = async (
			packagePaths: readonly string[],
		): Promise<readonly FacetBundleArtifact[]> => {
			const reloaded = await buildPluginSelection(packagePaths);
			if (sameStrings(defaultPluginSelection.packagePaths, reloaded.packagePaths)) {
				defaultPluginSelection = reloaded;
			}
			for (const [sessionPath, selected] of sessionPluginSelections) {
				if (sameStrings(selected.packagePaths, reloaded.packagePaths)) {
					sessionPluginSelections.set(sessionPath, reloaded);
				}
			}
			return reloaded.presentationArtifacts;
		};
		const socketPath = getUnixSocketPath(serverId, directory);
		const controlPath = join(directory, `control-${serverId}.sock`);
		const serverNonce = randomUUID().replaceAll("-", "").slice(0, 12);
		const serverPath = join(directory, `server-${serverId}-${serverNonce}.sock`);
		startupLease = await ensureCoordinator(socketPath, controlPath);
		coordinator = new CoordinatorConnection({ controlPath, endpoint: serverPath });
		const sessionDir = resolveSessionDirectory(options.sessionDir);
		workers = new SessionWorkerManager(coordinator, sessionDir, workerModel, (count) =>
			lifetime.setWorkerCount(count),
		);
		backend = await startServerBackend(
			{
				path: serverPath,
				serverId,
				sessionDir: options.sessionDir,
				resolveSessionPlugins,
				removeSessionPlugins,
				reloadPresentationFacetBundles,
			},
			workers,
			(count) => lifetime.setConnectionCount(count),
		);
		await coordinator.connect();
		startupLease.close();
		startupLease = undefined;
		await workers.discover(coordinator.peerIds);
		await backend.refreshSessions();
		relay = new RadiusRelayHost({
			serverId,
			server: backend.server,
			auth: new RadiusRelayAuthResolver(options.relayAuth),
			onStatus: options.onRelayStatus,
		});
		relay.start();

		const activeBackend = backend;
		const activeCoordinator = coordinator;
		const activeWorkers = workers;
		const activeRelay = relay;
		void activeCoordinator.replaced
			.then(async () => {
				lifetime.stop();
				activeWorkers.detach();
				await activeRelay.close();
				await activeBackend.close();
			})
			.finally(() => activeCoordinator.close())
			.catch(() => {});
		let closePromise: Promise<void> | undefined;
		const runtime: RunningServer = {
			serverId,
			sessionDir: activeBackend.sessionDir,
			socketPath,
			server: activeBackend.server,
			workerPids: activeWorkers.workerPids,
			closed: activeBackend.closed.finally(() => activeRelay.close()),
			close() {
				lifetime.stop();
				closePromise ??= (async () => {
					try {
						await activeRelay.close();
						await activeBackend.close();
					} finally {
						try {
							if (activeCoordinator.wasReplaced) activeWorkers.detach();
							else await activeWorkers.shutdown();
						} finally {
							activeCoordinator.close();
						}
					}
				})();
				return closePromise;
			},
		};
		lifetime.start(() => {
			void runtime.close().catch(() => {});
		});
		released = true;
		await release();
		return runtime;
	} catch (error) {
		lifetime.stop();
		startupLease?.close();
		if (coordinator?.wasReplaced) workers?.detach();
		const cleanup = await Promise.allSettled([
			relay?.close(),
			backend?.close(),
			coordinator?.wasReplaced ? undefined : workers?.shutdown(),
			Promise.resolve(coordinator?.close()),
			released ? undefined : release(),
		]);
		const cleanupErrors = cleanup.flatMap((result) => (result.status === "rejected" ? [result.reason] : []));
		if (cleanupErrors.length > 0) {
			throw new AggregateError([error, ...cleanupErrors], "Server runtime startup and cleanup failed");
		}
		throw error;
	}
}

async function startForegroundServer(
	options: Omit<StartServerOptions, "keepAlive"> = {},
): Promise<RunningServer> {
	const directory = resolveServerDirectory(options.directory);
	await ensurePrivateServerDirectory(directory);
	const profile = await acquireServerProfile(directory, options.serverId ?? process.env[ENV_SERVER_ID]);
	const serverId = profile.serverId;
	await profile.release();
	const release = await acquireServerActivation(directory, serverId);
	try {
		return await startServer({
			...options,
			directory,
			serverId,
			keepAlive: true,
		});
	} finally {
		await release();
	}
}

function parseServerModelOptions(value: string | undefined): { provider?: string; model: string } | undefined {
	if (value === undefined) return undefined;
	let parsed: unknown;
	try {
		parsed = JSON.parse(value);
	} catch (error) {
		throw new Error("Internal server received invalid model options", { cause: error });
	}
	if (typeof parsed !== "object" || parsed === null || Array.isArray(parsed)) {
		throw new Error("Internal server received invalid model options");
	}
	const keys = Object.keys(parsed);
	const model = "model" in parsed ? parsed.model : undefined;
	const provider = "provider" in parsed ? parsed.provider : undefined;
	if (
		keys.some((key) => key !== "provider" && key !== "model") ||
		typeof model !== "string" ||
		model.length === 0 ||
		(provider !== undefined && (typeof provider !== "string" || provider.length === 0))
	) {
		throw new Error("Internal server received invalid model options");
	}
	return provider === undefined ? { model } : { provider, model };
}

async function runServerProcess(args: readonly string[]): Promise<void> {
	const [directory, serverId, sessionDir, serializedModel] = args;
	if (args.length > 4) throw new Error("Internal server received unexpected arguments");
	if (!directory || !isAbsolute(directory)) throw new Error("Internal server requires an absolute server directory");
	if (!isServerId(serverId)) throw new Error("Internal server requires a canonical server ID");
	if (!sessionDir || !isAbsolute(sessionDir))
		throw new Error("Internal server requires an absolute Session directory");
	const workerModel = parseServerModelOptions(serializedModel);

	const runtime = await startServer({
		directory,
		serverId,
		sessionDir,
		keepAlive: false,
		...workerModel,
	});
	const close = (): void => {
		void runtime.close().catch(() => {});
	};
	process.once("SIGINT", close);
	process.once("SIGTERM", close);
	try {
		await runtime.closed;
	} finally {
		process.off("SIGINT", close);
		process.off("SIGTERM", close);
		await runtime.close();
	}
}

function sameStrings(left: readonly string[], right: readonly string[]): boolean {
	return left.length === right.length && left.every((value, index) => value === right[index]);
}

function createAgentController(harness: Harness, conversation: Conversation): AgentControllerService {
	const queue = async (
		whenBusy: "steer" | "followUp",
		request: AgentPromptRequest,
		context: Context,
	): Promise<AgentQueueResponse> => {
		try {
			const submission = await conversation.submit({ type: "input", content: toInput(request), whenBusy }, context);
			return { accepted: true, entryId: String(submission.id), error: null };
		} catch (error) {
			return { accepted: false, entryId: null, error: toAgentError(error) };
		}
	};

	return {
		async prompt(request, context) {
			try {
				const submission = await conversation.submit(
					{ type: "input", content: toInput(request), whenBusy: "reject" },
					context,
				);
				return { accepted: true, operationId: String(submission.id), error: null };
			} catch (error) {
				return { accepted: false, operationId: null, error: toAgentError(error) };
			}
		},
		steer: (request, context) => queue("steer", request, context),
		followUp: (request, context) => queue("followUp", request, context),
		async cancelQueued(entryId, context) {
			const id = parseSubmissionId(entryId);
			if (id === undefined) return { outcome: "not_found" };
			const result = await harness.abortSubmission(id, context, conversation.id);
			return {
				outcome: result === "aborted" ? "cancelled" : result === "not_found" ? "not_found" : "already_consumed",
			};
		},
		abort: (context) => conversation.abort(context),
		async compact(request, context) {
			try {
				const id = await conversation.compact(request.customInstructions ?? undefined, context);
				return { accepted: true, operationId: String(id), error: null };
			} catch (error) {
				return { accepted: false, operationId: null, error: toAgentError(error) };
			}
		},
		async waitForPrompt(operationId, context): Promise<AgentPromptResult> {
			const id = parseSubmissionId(operationId);
			const submission = id === undefined ? undefined : await harness.submission(id, context);
			if (submission === undefined) throw new Error(`Unknown prompt: ${operationId}`);
			const settled = await submission.wait(context);
			if (settled.status === "unanswered") return { status: "unanswered", text: null, reason: settled.reason };
			const answer = settled.type === "input" ? settled.answer : undefined;
			const message =
				answer === undefined ? undefined : (await harness.commit((tx) => tx.entry(answer), context))?.model?.[0];
			const text =
				message?.role === "assistant"
					? message.content.flatMap((content) => (content.type === "text" ? [content.text] : [])).join("")
					: "";
			return { status: "done", text, reason: null };
		},
	};
}

function parseSubmissionId(value: string): SubmissionId | undefined {
	const id = Number(value);
	return /^[1-9][0-9]*$/.test(value) && Number.isSafeInteger(id) ? (id as SubmissionId) : undefined;
}

function toInput(request: AgentPromptRequest): UserInput {
	if (request.images === null || request.images.length === 0) return request.message;
	const content: (TextContent | ImageContent)[] = [{ type: "text", text: request.message }, ...request.images];
	return content;
}

function toAgentError(error: unknown): AgentOperationError {
	if (error instanceof ConversationBusy) return { code: "busy", message: error.message };
	return { code: "operation_failed", message: error instanceof Error ? error.message : String(error) };
}

interface AgentPromptImage {
	type: "image";
	data: string;
	mimeType: string;
}

interface AgentPromptRequest {
	message: string;
	images: AgentPromptImage[] | null;
}

interface AgentOperationError {
	code: string;
	message: string;
}

type AgentOperationResponse =
	| { accepted: true; operationId: string; error: null }
	| { accepted: false; operationId: null; error: AgentOperationError };

type AgentQueueResponse =
	| { accepted: true; entryId: string; error: null }
	| { accepted: false; entryId: null; error: AgentOperationError };

type AgentPromptResult =
	| { status: "done"; text: string; reason: null }
	| { status: "unanswered"; text: null; reason: string };

interface AgentCompactionRequest {
	customInstructions: string | null;
}

type ServerConnectionState =
	| { status: "connecting"; attempt: number }
	| { status: "connected"; since: string }
	| { status: "disconnected"; since: string; reason: string; retryAt: string | null };

type SessionAttachmentState =
	| { status: "detached" }
	| { status: "attaching" | "attached" | "degraded"; sessionId: string };

interface ServerServiceSource extends RemoteServiceSource {
	readonly connection: ReplicatedState<ServerConnectionState>;
	dispose(context: Context): Promise<void>;
}

interface SessionServiceSource extends RemoteServiceSource {
	readonly attachment: ReplicatedState<SessionAttachmentState>;
	/** Wait for the exact current attachment generation to finish hydrating. */
	whenAttached(sessionId: string, context: Context): Promise<void>;
	/** Wait for every binding to finish releasing the previous attachment. */
	whenDetached(context: Context): Promise<void>;
	dispose(context: Context): Promise<void>;
}

interface ServiceSourceOptions {
	readonly onError?: (error: Error) => void;
}

class RoutedServiceBinding implements RemoteServices {
	readonly #services: RemoteServiceBinding;
	readonly #getBound: () => boolean;
	readonly #onActivate: (context: Context) => Promise<void>;
	readonly #remove: () => void;
	#activated = false;
	#activationComplete = false;

	constructor(options: {
		readonly services: readonly { readonly id: string }[];
		readonly transport: RemoteServiceTransport;
		readonly getBound: () => boolean;
		readonly assertAccess: () => void;
		readonly onError: (error: Error) => void;
		readonly onActivate?: (context: Context) => Promise<void>;
		readonly remove: () => void;
	}) {
		this.#services = createRemoteServiceBinding({
			services: options.services,
			transport: options.transport,
			bound: false,
			assertAccess: options.assertAccess,
			onError: options.onError,
		});
		this.#getBound = options.getBound;
		this.#onActivate = options.onActivate ?? (() => Promise.resolve());
		this.#remove = options.remove;
	}

	use<T>(service: Service<T>): T {
		return this.#services.use(service);
	}

	observe<T>(service: Service<T>, handler: (service: T, context: Context) => void | Promise<void>): () => void {
		return this.#services.observe(service, handler);
	}

	async ready(context: Context): Promise<void> {
		if (!this.#activated) {
			this.#activated = true;
			await this.#services.rebind(this.#getBound(), context);
		}
		await this.serviceReady(context);
		if (!this.#activationComplete) {
			await this.#onActivate(context);
			this.#activationComplete = true;
		}
	}

	serviceReady(context: Context): Promise<void> {
		return this.#services.ready(context);
	}

	updateBound(bound: boolean, context: Context): Promise<void> {
		return this.#activated ? this.#services.rebind(bound, context) : Promise.resolve();
	}

	async dispose(context: Context): Promise<void> {
		this.#remove();
		await this.#services.dispose(context);
	}
}

use<T>(service: Service<T>): T {
		return this.#services.use(service);
	}

observe<T>(service: Service<T>, handler: (service: T, context: Context) => void | Promise<void>): () => void {
		return this.#services.observe(service, handler);
	}

async ready(context: Context): Promise<void> {
		if (!this.#activated) {
			this.#activated = true;
			await this.#services.rebind(this.#getBound(), context);
		}
		await this.serviceReady(context);
		if (!this.#activationComplete) {
			await this.#onActivate(context);
			this.#activationComplete = true;
		}
	}

serviceReady(context: Context): Promise<void> {
		return this.#services.ready(context);
	}

updateBound(bound: boolean, context: Context): Promise<void> {
		return this.#activated ? this.#services.rebind(bound, context) : Promise.resolve();
	}

async dispose(context: Context): Promise<void> {
		this.#remove();
		await this.#services.dispose(context);
	}

class ServerServiceSourceImpl implements ServerServiceSource {
	readonly acceptsUnavailableServices = false;
	readonly connection: ReplicatedState<ServerConnectionState>;
	readonly #client: Client;
	readonly #transport: RemoteServiceTransport;
	readonly #bindings = new Set<RoutedServiceBinding>();
	readonly #removeConnectionListener: () => void;
	readonly #onError: (error: Error) => void;
	#transition = Promise.resolve();
	#connectionAttempt: number;
	#disposed = false;

	constructor(client: Client, options: ServiceSourceOptions) {
		this.#client = client;
		this.#transport = createClientServiceTransport(client, () => ({ serverId: client.serverId }));
		this.#onError = options.onError ?? (() => {});
		this.#connectionAttempt = client.connectionState === "connecting" ? 1 : 0;
		const connectionState = replicatedState<ServerConnectionState>(
			toServerConnectionState(client, this.#connectionAttempt),
		);
		this.connection = connectionState;
		this.#removeConnectionListener = client.onConnectionStateChange(({ state, error }) => {
			if (state === "connecting") this.#connectionAttempt += 1;
			publishReplacement(
				connectionState,
				toServerConnectionState(client, this.#connectionAttempt, error),
				BACKGROUND_CONTEXT,
			);
			this.#transition = this.#transition
				.then(async () => {
					const results = await Promise.allSettled(
						[...this.#bindings].map((binding) => binding.updateBound(state === "connected", BACKGROUND_CONTEXT)),
					);
					const failures = results.filter(
						(result): result is PromiseRejectedResult => result.status === "rejected",
					);
					if (failures.length > 0) throw new AggregateError(failures.map(({ reason }) => reason));
				})
				.catch((transitionError: unknown) => this.#onError(toError(transitionError)));
		});
	}

	catalogue(context: Context) {
		return this.#client.serviceCatalogue({ serverId: this.#client.serverId }, context.abortSignal);
	}

	open(options: {
		readonly services: readonly { readonly id: string }[];
		assertAccess(): void;
		onError(error: Error): void;
	}): RemoteServices {
		if (this.#disposed) throw new Error("Server service source is disposed");
		let binding!: RoutedServiceBinding;
		binding = new RoutedServiceBinding({
			services: options.services,
			transport: this.#transport,
			getBound: () => this.#client.connected,
			assertAccess: options.assertAccess,
			onError: options.onError,
			remove: () => this.#bindings.delete(binding),
		});
		this.#bindings.add(binding);
		return binding;
	}

	async dispose(context: Context): Promise<void> {
		if (this.#disposed) return;
		this.#disposed = true;
		this.#removeConnectionListener();
		await this.#transition;
		const bindings = [...this.#bindings];
		this.#bindings.clear();
		const results = await Promise.allSettled(bindings.map((binding) => binding.dispose(context)));
		throwFailures(results, "Failed to dispose server service source");
	}
}

catalogue(context: Context) {
		return this.#client.serviceCatalogue({ serverId: this.#client.serverId }, context.abortSignal);
	}

open(options: {
		readonly services: readonly { readonly id: string }[];
