function documentCreate(definition: AnyDocDefinition, address: DocumentAddress, id: DocumentId): DocumentCreate {
	const key = address.key === undefined ? {} : { key: address.key };
	switch (address.scope.kind) {
		case "session":
			return { id, kind: address.kind, ...key, scope: address.scope };
		case "task":
			return { id, kind: address.kind, ...key, scope: address.scope };
		case "conversation":
			return {
				id,
				kind: address.kind,
				...key,
				scope: address.scope,
				history: definition.history!,
				fork: definition.fork!,
			} as DocumentCreate;
	}
}

