		_context: Context,
	): Promise<Page<ConversationRecord, Cursor>> {
		this.assertOpen();
		const clauses = ["id > ?"];
		const params: SqliteValue[] = [cursorId(cursor) ?? -1];
		if (query.ownerConversationId !== undefined) {
			clauses.push("owner_conversation_id = ?");
