interface StorageConformanceRunner {
	readonly describe: (name: string, suite: () => void) => unknown;
	readonly expect: ExpectLike;
	readonly it: (name: string, test: () => Promise<void>) => unknown;
}

function registerStorageConformance(
	runner: StorageConformanceRunner,
	name: string,
	withStorage: StorageConformanceProvider,
): void {
	const cases = createStorageConformance({
		assertions: createExpectAssertions(runner.expect),
		withStorage,
	});
	runner.describe(name, () => {
		for (const testCase of cases) runner.it(testCase.name, testCase.run);
	});
}

packages/durable/src/testing/storage-ben.source_code:
type StorageBenchmarkScale = {
	readonly name: string;
	readonly entryCount: number;
	readonly taskCount: number;
	readonly documentCount: number;
};

function storageBenchmarkPrimaryRecordCount(scale: StorageBenchmarkScale): number {
	return (
		1 +
		scale.entryCount +
		scale.taskCount +
		scale.documentCount +
		REPLAY_TAILS.length +
		1 +
		FORK_DEPTH * (1 + ENTRIES_PER_FORK)
	);
}

type StorageBenchmarkDataset = {
	readonly firstEntryId: EntryId;
	readonly filteredTaskCount: number;
	readonly exactDocumentId: DocumentId;
	readonly exactDocumentKey: string;
	readonly replayDocumentIds: Readonly<Record<(typeof REPLAY_TAILS)[number], DocumentId>>;
	readonly historicalDocumentId: DocumentId;
	readonly ancientAt: Seq;
	readonly recentAt: Seq;
	readonly deepestConversationId: ConversationId;
	readonly ancestorHeadEntryId: EntryId;
};

function task(id: TaskId<JsonValue>, index: number): StoredTask {
	const statuses = ["pending", "running", "terminal"] as const;
	const status = statuses[index % statuses.length];
	const common = {
		id,
		conversationId: ROOT_CONVERSATION_ID,
		kind: index % 4 === 0 ? "benchmark.filtered" : "benchmark.other",
		version: 1,
		input: { index },
		background: index % 5 === 0,
		abortRequested: index % 7 === 0,
	};
	if (status === "terminal") {
		return { ...common, state: { status, outcome: { status: "completed", result: { index } } } };
	}
	return { ...common, state: { status, checkpoint: { index, payload: "x".repeat(64) } } };
}

async function seedStorageBenchmark(
	storage: Storage,
	scale: StorageBenchmarkScale = TIMING_SCALE,
): Promise<StorageBenchmarkDataset> {
	await storage.commit([{ type: "conversation", value: { id: ROOT_CONVERSATION_ID } }], BACKGROUND_CONTEXT);

	let firstEntryId: EntryId | undefined;
	for (let start = 0; start < scale.entryCount; start += BATCH_SIZE) {
		const writes: StorageWrite[] = [];
		for (let index = start; index < Math.min(start + BATCH_SIZE, scale.entryCount); index++) {
			const id = await storage.mintId<EntryId>();
			if (index === 0) firstEntryId = id;
			writes.push({
				type: "entry",
				value: {
					id,
					conversationId: ROOT_CONVERSATION_ID,
					kind: "benchmark.entry",
					...(index === 0 ? { head: id } : {}),
					data: { index, text: `entry-${index}-${"x".repeat(96)}` },
				},
			});
		}
		await storage.commit(writes, BACKGROUND_CONTEXT);
	}

	for (let start = 0; start < scale.taskCount; start += BATCH_SIZE) {
		const writes: StorageWrite[] = [];
		for (let index = start; index < Math.min(start + BATCH_SIZE, scale.taskCount); index++) {
			writes.push({ type: "task", value: task(await storage.mintId<TaskId<JsonValue>>(), index) });
		}
		await storage.commit(writes, BACKGROUND_CONTEXT);
	}

	let exactDocumentId: DocumentId | undefined;
	for (let start = 0; start < scale.documentCount; start += BATCH_SIZE) {
		const writes: StorageWrite[] = [];
		for (let index = start; index < Math.min(start + BATCH_SIZE, scale.documentCount); index++) {
			const id = await storage.mintId<DocumentId>();
			exactDocumentId = id;
			writes.push({
				type: "document.create",
				record: { id, kind: "benchmark.family", key: `key-${index}`, scope: { kind: "session" } },
				content: { kind: "base", version: 1, value: { index, text: "x".repeat(128) } },
			});
		}
		await storage.commit(writes, BACKGROUND_CONTEXT);
	}

	const replayEntries = await Promise.all(
		REPLAY_TAILS.map(async (tail) => {
			const id = await storage.mintId<DocumentId>();
			return { tail, id };
		}),
	);
	await storage.commit(
		replayEntries.map(({ tail, id }) => ({
			type: "document.create" as const,
			record: {
				id,
				kind: "benchmark.replay",
				key: String(tail),
				scope: { kind: "conversation" as const, conversationId: ROOT_CONVERSATION_ID },
				history: "rewindable" as const,
				fork: "asOf" as const,
			},
			content: { kind: "base" as const, version: 1, value: { count: 0, text: "x".repeat(64) } },
		})),
		BACKGROUND_CONTEXT,
	);
	for (let count = 1; count <= REPLAY_TAILS.at(-1)!; count++) {
		await storage.commit(
			replayEntries
				.filter(({ tail }) => count <= tail)
				.map(({ id }) => ({
					type: "document.change" as const,
					id,
					content: { kind: "delta" as const, version: 1, ops: [["s", ["count"], count] as const] },
				})),
			BACKGROUND_CONTEXT,
		);
	}

	const historicalDocumentId = await storage.mintId<DocumentId>();
	const historicalRecord = {
		id: historicalDocumentId,
		kind: "benchmark.history",
		scope: { kind: "conversation", conversationId: ROOT_CONVERSATION_ID },
		history: "rewindable",
		fork: "asOf",
	} satisfies DocumentCreate;
	await storage.commit(
		[
			{
				type: "document.create",
				record: historicalRecord,
				content: { kind: "base", version: 1, value: { count: 0 } },
			},
		],
		BACKGROUND_CONTEXT,
	);
	let ancientAt: Seq | undefined;
	for (let count = 1; count <= HISTORY_SEGMENT_LENGTH; count++) {
		ancientAt = await storage.commit(
			[
				{
					type: "document.change",
					id: historicalDocumentId,
					content: { kind: "delta", version: 1, ops: [["s", ["count"], count]] },
				},
			],
			BACKGROUND_CONTEXT,
		);
	}
	await storage.commit(
		[
			{
				type: "document.change",
				id: historicalDocumentId,
				content: { kind: "base", version: 1, value: { count: HISTORY_SEGMENT_LENGTH } },
			},
		],
		BACKGROUND_CONTEXT,
	);
	if (ancientAt === undefined) throw new Error("Benchmark history seed produced no commits");
	let recentAt = ancientAt;
	for (let count = HISTORY_SEGMENT_LENGTH + 1; count <= HISTORY_SEGMENT_LENGTH * 2; count++) {
		recentAt = await storage.commit(
			[
				{
					type: "document.change",
					id: historicalDocumentId,
					content: { kind: "delta", version: 1, ops: [["s", ["count"], count]] },
				},
			],
			BACKGROUND_CONTEXT,
		);
	}

	if (firstEntryId === undefined) throw new Error("Benchmark scale must create entries");
	let parentConversationId = ROOT_CONVERSATION_ID;
	let parentAt = firstEntryId;
	let deepestConversationId = ROOT_CONVERSATION_ID;
	for (let depth = 0; depth < FORK_DEPTH; depth++) {
		const conversationId = await storage.mintId<ConversationId>();
		await storage.commit(
			[
				{
					type: "conversation",
					value: { id: conversationId, parent: { conversationId: parentConversationId, at: parentAt } },
				},
			],
			BACKGROUND_CONTEXT,
		);
		const ids = await Promise.all(Array.from({ length: ENTRIES_PER_FORK }, () => storage.mintId<EntryId>()));
		await storage.commit(
			ids.map((id, index) => ({
				type: "entry" as const,
				value: {
					id,
					conversationId,
					kind: "benchmark.fork",
					data: { depth, index },
				},
			})),
			BACKGROUND_CONTEXT,
		);
		parentConversationId = conversationId;
		parentAt = ids.at(-1)!;
		deepestConversationId = conversationId;
	}

	if (exactDocumentId === undefined) throw new Error("Benchmark scale must create documents");
	return {
		firstEntryId,
		filteredTaskCount: Math.min(50, Math.ceil(scale.taskCount / 60)),
		exactDocumentId,
		exactDocumentKey: `key-${scale.documentCount - 1}`,
		replayDocumentIds: Object.fromEntries(replayEntries.map(({ tail, id }) => [tail, id])) as Record<
			(typeof REPLAY_TAILS)[number],
			DocumentId
		>,
		historicalDocumentId,
		ancientAt,
		recentAt,
		deepestConversationId,
		ancestorHeadEntryId: firstEntryId,
	};
}

type StorageReadBenchmark = {
	readonly name: string;
	run(storage: Storage, dataset: StorageBenchmarkDataset): Promise<number>;
	expected(dataset: StorageBenchmarkDataset): number;
};

async run(storage) {
			const entryId = await storage.mintId<EntryId>();
			const taskId = await storage.mintId<TaskId<JsonValue>>();
			const submissionId = await storage.mintId<SubmissionId>();
			const documentId = await storage.mintId<DocumentId>();
			const writes: readonly StorageWrite[] = [
				{
					type: "entry",
					value: { id: entryId, conversationId: ROOT_CONVERSATION_ID, kind: "benchmark.mixed" },
				},
				{ type: "task", value: task(taskId, taskId) },
				{
					type: "submission",
					value: {
						id: submissionId,
						conversationId: ROOT_CONVERSATION_ID,
						requestId: `benchmark-${submissionId}`,
						type: "write",
						status: "done",
						entry: entryId,
					},
				},
				{
					type: "document.create",
					record: { id: documentId, kind: "benchmark.mixed", key: String(documentId), scope: { kind: "session" } },
					content: { kind: "base", version: 1, value: { entryId, taskId } },
				},
			];
			await storage.commit(writes, BACKGROUND_CONTEXT);
			return writes.length;
		}

type StorageWriteBenchmark = {
	readonly name: string;
	readonly expected: number;
	run(storage: Storage): Promise<number>;
};

async function seedStorageWriteBenchmark(storage: Storage): Promise<void> {
	await storage.commit([{ type: "conversation", value: { id: ROOT_CONVERSATION_ID } }], BACKGROUND_CONTEXT);
	await storage.commit(
		await Promise.all(
			Array.from({ length: 100 }, async (_, index) => ({
				type: "entry" as const,
				value: {
					id: await storage.mintId<EntryId>(),
					conversationId: ROOT_CONVERSATION_ID,
					kind: "benchmark.baseline",
					data: { index },
				},
			})),
		),
		BACKGROUND_CONTEXT,
	);
}

packages/durable/src/testing/storage-con.source_code:
async function createRoot(storage: Storage): Promise<ConversationId> {
	await storage.commit([{ type: "conversation", value: { id: ROOT_CONVERSATION_ID } }], context);
	return ROOT_CONVERSATION_ID;
}

function pendingTask(id: TaskId<JsonValue>, conversationId: ConversationId, phase = "ready") {
	return {
		id,
		conversationId,
		kind: "test.task",
		version: 1,
		input: { value: id },
		state: { status: "pending", checkpoint: { phase } },
		background: false,
		abortRequested: false,
	} satisfies StoredTask;
}

function entry(
	id: EntryId,
	conversationId: ConversationId,
	kind = "message",
	extra: Partial<EntryRecord> = {},
): EntryRecord {
	return { id, conversationId, kind, ...extra };
}

type AssertionResult = {
	toBe(expected: unknown): void;
	toBeDefined(): void;
	toBeGreaterThan(expected: number): void;
	toBeUndefined(): void;
	toEqual(expected: unknown): void;
	toHaveLength(expected: number): void;
	toMatchObject(expected: unknown): void;
	readonly rejects: { toThrow(messageIncludes: string): Promise<void> };
	readonly resolves: { toBe(expected: unknown): Promise<void> };
};

function assertionFacade(assertions: StorageConformanceAssertions) {
	return (actual: unknown): AssertionResult => ({
		toBe: (expected) => assertions.strictEqual(actual, expected),
		toBeDefined: () => assertions.ok(actual !== undefined, "Expected value to be defined"),
		toBeGreaterThan: (expected) => assertions.greaterThan(actual as number, expected),
		toBeUndefined: () => assertions.strictEqual(actual, undefined),
		toEqual: (expected) => assertions.deepEqual(actual, expected),
		toHaveLength: (expected) => assertions.strictEqual((actual as { readonly length: unknown }).length, expected),
		toMatchObject: (expected) => assertions.partialDeepEqual(actual, expected),
		rejects: {
			toThrow: (messageIncludes) => assertions.rejects(Promise.resolve(actual), messageIncludes),
		},
		resolves: {
			toBe: async (expected) => assertions.strictEqual(await Promise.resolve(actual), expected),
		},
	});
}

function createCase(options: StorageConformanceOptions, name: string, test: ConformanceTest): StorageConformanceCase {
	return { name, run: () => options.withStorage(test) };
}

function createStorageConformance(options: StorageConformanceOptions): readonly StorageConformanceCase[] {
	const expect = assertionFacade(options.assertions);
	return [
		createCase(options, "reserves ID 1 for the immutable root conversation", async (storage) => {
			expect(await storage.mintId<ConversationId>()).toBe(2);
			await expect(createRoot(storage)).resolves.toBe(ROOT_CONVERSATION_ID);
			expect(await storage.conversation(ROOT_CONVERSATION_ID, context)).toEqual({ id: ROOT_CONVERSATION_ID });
			await expect(
				storage.commit([{ type: "conversation", value: { id: ROOT_CONVERSATION_ID } }], context),
			).rejects.toThrow(`ID ${ROOT_CONVERSATION_ID} already belongs to conversation`);
		}),

		createCase(
			options,
			"commits mixed table writes atomically and rolls all of them back on failure",
			async (storage) => {
				const rootId = await createRoot(storage);
				const entryId = await storage.mintId<EntryId>();
				const taskId = await storage.mintId<TaskId<JsonValue>>();
				const submissionId = await storage.mintId<SubmissionId>();
				const task = pendingTask(taskId, rootId);
				const input: SubmissionRecord = {
					id: submissionId,
					conversationId: rootId,
					requestId: "request-1",
					type: "input",
					status: "placed",
					entry: entryId,
				};
				const initialSeq = await storage.commit(
					[
						{ type: "entry", value: entry(entryId, rootId, "user", { data: { text: "hello" } }) },
						{ type: "task", value: task },
						{ type: "submission", value: input },
					],
					context,
				);

				expect(await storage.entry(entryId, context)).toEqual({
					entry: entry(entryId, rootId, "user", { data: { text: "hello" } }),
					commitSeq: initialSeq,
				});
				expect(await storage.task(taskId, context)).toEqual(task);
				expect(await storage.submission(submissionId, context)).toEqual(input);

				const transientEntryId = await storage.mintId<EntryId>();
				const runningTask: StoredTask = {
					...task,
					state: { status: "running", checkpoint: { phase: "effect" } },
				};
				const doneInput: SubmissionRecord = { ...input, status: "done", answer: transientEntryId };
				await expect(
					storage.commit(
						[
							{ type: "task", value: runningTask },
							{ type: "submission", value: doneInput },
							{ type: "entry", value: entry(transientEntryId, rootId, "assistant") },
							{ type: "conversation", value: { id: rootId } },
						],
						context,
					),
				).rejects.toThrow(`ID ${rootId} already belongs to conversation`);

				expect(await storage.task(taskId, context)).toEqual(task);
				expect(await storage.submission(submissionId, context)).toEqual(input);
				expect(await storage.entry(transientEntryId, context)).toBeUndefined();
				const afterRollbackSeq = await storage.commit(
					[{ type: "entry", value: entry(await storage.mintId<EntryId>(), rootId, "after-rollback") }],
					context,
				);
				expect(afterRollbackSeq).toBeGreaterThan(initialSeq);
			},
		),

		createCase(options, "detaches retained writes and every returned record", async (storage) => {
			const rootId = await createRoot(storage);
			const entryId = await storage.mintId<EntryId>();
			const taskId = await storage.mintId<TaskId<JsonValue>>();
			const submissionId = await storage.mintId<SubmissionId>();
			const entryData = { nested: [1, 2] };
			const checkpoint = { phase: "ready", nested: { count: 1 } };
			const detail = { codes: ["initial"] };
			const storedEntry = entry(entryId, rootId, "note", { data: entryData });
			const storedTask: StoredTask = {
				...pendingTask(taskId, rootId),
				state: { status: "pending", checkpoint },
			};
			const storedInput: SubmissionRecord = {
				id: submissionId,
				conversationId: rootId,
				type: "input",
				status: "unanswered",
				reason: "failed",
				detail,
			};
			await storage.commit(
				[
					{ type: "entry", value: storedEntry },
					{ type: "task", value: storedTask },
					{ type: "submission", value: storedInput },
				],
				context,
			);

			entryData.nested.push(3);
			checkpoint.nested.count = 2;
			detail.codes.push("mutated");
			expect((await storage.entry(entryId, context))?.entry.data).toEqual({ nested: [1, 2] });
			expect((await storage.task(taskId, context))?.state).toEqual({
				status: "pending",
				checkpoint: { phase: "ready", nested: { count: 1 } },
			});
			expect((await storage.submission(submissionId, context))?.detail).toEqual({ codes: ["initial"] });

			const readEntry = (await storage.entry(entryId, context))!.entry;
			(readEntry.data as { nested: number[] }).nested.push(9);
			const readTask = (await storage.task(taskId, context))!;
			if (readTask.state.status !== "terminal") {
				(readTask.state.checkpoint as { phase: string; nested: { count: number } }).nested.count = 9;
			}
			const readInput = (await storage.submission(submissionId, context))!;
			(readInput.detail as { codes: string[] }).codes.push("read mutation");

			expect((await storage.entry(entryId, context))?.entry.data).toEqual({ nested: [1, 2] });
			expect((await storage.task(taskId, context))?.state).toEqual({
				status: "pending",
				checkpoint: { phase: "ready", nested: { count: 1 } },
			});
			expect((await storage.submission(submissionId, context))?.detail).toEqual({ codes: ["initial"] });
		}),

		createCase(options, "detaches prototype-like JSON keys without changing object prototypes", async (storage) => {
			const rootId = await createRoot(storage);
			const entryId = await storage.mintId<EntryId>();
			const data = JSON.parse(
				'{"__proto__":{"polluted":false},"constructor":{"label":"stored"},"toString":"value"}',
			) as Record<string, JsonValue>;
			await storage.commit([{ type: "entry", value: entry(entryId, rootId, "note", { data }) }], context);

