function colorToRgb(color: Color): RgbColor {
	switch (color.kind) {
		case "indexed":
			return indexedToRgb(color.index);
		case "rgb":
			return { r: color.r, g: color.g, b: color.b };
		case "oklch":
			return oklchToRgb(color);
	}
}

