import { fileURLToPath } from "node:url";
import { defineConfig } from "vitest/config";

const src = (path: string): string => fileURLToPath(new URL(path, import.meta.url));

/**
 * Exact matches for bare specifiers, plus one rule per package for subpath exports such as
 * `@earendil-works/pi-ai/utils/uuid`. A prefix alias would rewrite those onto `index.ts/utils/uuid`.
 */
export default defineConfig({
	test: {
		globals: true,
		environment: "node",
		reporters: process.env.GITHUB_ACTIONS ? ["dot", "github-actions"] : ["dot"],
	},
	resolve: {
		conditions: ["source"],
		alias: [
			{ find: /^@earendil-works\/pi-agent-core$/, replacement: src("../agent/src/index.ts") },
			{ find: /^@earendil-works\/pi-agent-core\/(.+)$/, replacement: `${src("../agent/src/")}$1.ts` },
			{ find: /^@earendil-works\/pi-ai$/, replacement: src("../ai/src/index.ts") },
			{ find: /^@earendil-works\/pi-ai\/(.+)$/, replacement: `${src("../ai/src/")}$1.ts` },
			{ find: /^@earendil-works\/pi-telemetry$/, replacement: src("../telemetry/src/index.ts") },
			{ find: /^@earendil-works\/pi-protocol$/, replacement: src("../protocol/src/index.ts") },
		],
	},
	ssr: { resolve: { conditions: ["source"] } },
});

.github/workflows/approve-contributor.ym.source_code:
approve:
  runs-on: ubuntu-latest
  permissions:
    contents: write
    issues: write
    pull-requests: write
  steps:
    - name: Checkout
      uses: actions/checkout@3d3c42e5aac5ba805825da76410c181273ba90b1 # v7.0.1
      with:
        ref: ${{ github.event.repository.default_branch }}

    - name: Update contributor approval
      id: update
      uses: actions/github-script@3a2844b7e9c422d3c10d287c895573f7108da1b3 # v9.0.0
      with:
        script: |
          const fs = require('fs');

          const APPROVED_FILE = '.github/APPROVED_CONTRIBUTORS';
          const VALID_CAPABILITIES = new Set(['issue', 'pr']);
          const issueAuthor = context.payload.issue.user.login;
          const commenter = context.payload.comment.user.login;
          const commentBody = (context.payload.comment.body || '').trim();

          const approvalAtStartPattern = /^[\s.]*(?:@[A-Za-z0-9](?:[A-Za-z0-9-]{0,37}[A-Za-z0-9])?(?:\s*,\s*|[.:]\s*|\s+))*(lgtmi|lgtm)(?=$|[\s]|[^\p{L}\p{N}_\s])/iu;
          const approvalAtEndPattern = /(?:^|[\s.])(lgtmi|lgtm)\s*(?:[^\p{L}\p{N}_\s])?\s*$/iu;
          const approvalMatch = commentBody.match(approvalAtStartPattern) ?? commentBody.match(approvalAtEndPattern);

          if (!approvalMatch) {
            console.log('Comment does not start or end with lgtm or lgtmi');
            core.setOutput('status', 'skipped');
            return;
          }

          const targetCapability = approvalMatch[1].toLowerCase() === 'lgtmi' ? 'issue' : 'pr';

          try {
            const { data: permissionLevel } = await github.rest.repos.getCollaboratorPermissionLevel({
              owner: context.repo.owner,
              repo: context.repo.repo,
              username: commenter,
            });

            if (!['admin', 'maintain', 'write'].includes(permissionLevel.permission)) {
              console.log(`${commenter} does not have write access`);
              core.setOutput('status', 'skipped');
              return;
            }
          } catch {
            console.log(`${commenter} does not have collaborator access`);
            core.setOutput('status', 'skipped');
            return;
          }

          function parseMentionedUsers(body) {
            const users = [];
            const seenUsers = new Set();
            const mentionPattern = /(^|[^A-Za-z0-9_])@([A-Za-z0-9](?:[A-Za-z0-9-]{0,37}[A-Za-z0-9])?)(?![A-Za-z0-9-]|\/)/g;

            for (const match of body.matchAll(mentionPattern)) {
              const username = match[2];
              const normalizedUser = username.toLowerCase();
              if (seenUsers.has(normalizedUser)) {
                continue;
              }
              seenUsers.add(normalizedUser);
              users.push(username);
            }

            return users;
          }

          function parseApprovedUsers(content) {
            const lines = content.split('\n');
            const entries = [];
            const users = new Map();

            for (const line of lines) {
              const trimmed = line.trim();
              if (!trimmed || trimmed.startsWith('#')) {
                entries.push({ type: 'other', line });
                continue;
              }

              const parts = trimmed.split(/\s+/);
              if (parts.length !== 2) {
                console.log(`Skipping malformed line: ${line}`);
                entries.push({ type: 'other', line });
                continue;
              }

              const [username, capability] = parts;
              const normalizedCapability = capability.toLowerCase();
              if (!VALID_CAPABILITIES.has(normalizedCapability)) {
                console.log(`Skipping line with invalid capability: ${line}`);
                entries.push({ type: 'other', line });
                continue;
              }

              const normalizedUser = username.toLowerCase();
              const entry = { type: 'user', username, normalizedUser, capability: normalizedCapability };
              entries.push(entry);
              users.set(normalizedUser, entry);
            }

            return { entries, users };
          }

          function stringifyApprovedUsers(entries) {
            const normalizedEntries = [...entries];

            while (normalizedEntries.length > 0) {
              const lastEntry = normalizedEntries[normalizedEntries.length - 1];
              if (lastEntry.type !== 'other' || lastEntry.line.trim() !== '') {
                break;
              }
              normalizedEntries.pop();
            }

            return `${normalizedEntries
              .map((entry) => (entry.type === 'user' ? `${entry.username} ${entry.capability}` : entry.line))
              .join('\n')}\n`;
          }

          const content = fs.readFileSync(APPROVED_FILE, 'utf8');
          const { entries, users } = parseApprovedUsers(content);
          const mentionedUsers = parseMentionedUsers(commentBody);
          const approvalTargets = mentionedUsers.length > 0 ? mentionedUsers : [issueAuthor];
          const changedTargets = [];
          const alreadyTargets = [];

          for (const username of approvalTargets) {
            const normalizedUser = username.toLowerCase();
            const existingEntry = users.get(normalizedUser);
            const existingCapability = existingEntry?.capability ?? null;

            if (existingCapability === 'pr' || existingCapability === targetCapability) {
              alreadyTargets.push(existingEntry?.username ?? username);
              console.log(`${username} is already approved for ${existingCapability}`);
              continue;
            }

            if (existingEntry) {
              existingEntry.capability = targetCapability;
              changedTargets.push(existingEntry.username);
            } else {
              const entry = { type: 'user', username, normalizedUser, capability: targetCapability };
              entries.push(entry);
              users.set(normalizedUser, entry);
              changedTargets.push(username);
            }

            console.log(`Set ${username} capability to ${targetCapability}`);
          }

          core.setOutput('capability', targetCapability);
          core.setOutput('changed_targets', JSON.stringify(changedTargets));
          core.setOutput('already_targets', JSON.stringify(alreadyTargets));

          if (changedTargets.length === 0) {
            core.setOutput('status', 'already');
            return;
          }

          fs.writeFileSync(APPROVED_FILE, stringifyApprovedUsers(entries));
          core.setOutput('status', 'changed');

    - name: Commit and push
      if: steps.update.outputs.status == 'changed'
      run: |
        git config user.name "github-actions[bot]"
        git config user.email "github-actions[bot]@users.noreply.github.com"
        git add .github/APPROVED_CONTRIBUTORS
        git diff --staged --quiet || git commit -m "chore: approve contributors from issue #${{ github.event.issue.number }}"
        git push

    - name: Comment on issue
      if: steps.update.outputs.status == 'changed' || steps.update.outputs.status == 'already'
      uses: actions/github-script@3a2844b7e9c422d3c10d287c895573f7108da1b3 # v9.0.0
      env:
        CAPABILITY: ${{ steps.update.outputs.capability }}
        CHANGED_TARGETS: ${{ steps.update.outputs.changed_targets }}
        ALREADY_TARGETS: ${{ steps.update.outputs.already_targets }}
      with:
        script: |
          const capability = process.env.CAPABILITY;
          const changedTargets = JSON.parse(process.env.CHANGED_TARGETS || '[]');
          const alreadyTargets = JSON.parse(process.env.ALREADY_TARGETS || '[]');
          const defaultBranch = context.payload.repository.default_branch;
          const formatTargets = (targets) => targets.map((target) => `@${target}`).join(', ');
          const bodyLines = [];

          if (changedTargets.length > 0) {
            if (capability === 'issue') {
              bodyLines.push(`${formatTargets(changedTargets)} approved for issues. Future issues will not be auto-closed. PRs still require \`lgtm\` at the start of a maintainer reply (optionally after one or more \`@username\` mentions) or at the end.`);
            } else {
              bodyLines.push(`${formatTargets(changedTargets)} approved for issues and PRs. Future issues and PRs will not be auto-closed.`);
            }
          }

          if (alreadyTargets.length > 0) {
            const verb = alreadyTargets.length === 1 ? 'is' : 'are';
            bodyLines.push(`${formatTargets(alreadyTargets)} ${verb} already approved.`);
          }

          bodyLines.push('', `See [CONTRIBUTING.md](https://github.com/${context.repo.owner}/${context.repo.repo}/blob/${defaultBranch}/CONTRIBUTING.md).`);
          const body = bodyLines.join('\n');

          await github.rest.issues.createComment({
            owner: context.repo.owner,
            repo: context.repo.repo,
            issue_number: context.issue.number,
            body,
          });

.github/workflows/issue-analysis.yml::au.source_code:
authorize:
  runs-on: ubuntu-latest
  outputs:
    should_run: ${{ steps.verify.outputs.should_run }}
    extra_instructions: ${{ steps.verify.outputs.extra_instructions }}
    runs_on: ${{ steps.verify.outputs.runs_on }}
    runner_os: ${{ steps.verify.outputs.runner_os }}
    runner_profile: ${{ steps.verify.outputs.runner_profile }}
  steps:
    - name: Verify sender permission
      id: verify
      uses: actions/github-script@3a2844b7e9c422d3c10d287c895573f7108da1b3 # v9.0.0
      env:
        ORG_READ_TOKEN: ${{ secrets.EARENDIL_ORG_READ_TOKEN }}
      with:
        script: |
          const ANALYZE_LABEL = 'pi-analyze';
          const TRIGGER_RE = /@issuron\s+analyze\b/i;
          const RUN_ON_TAG_RE = /#run-on-([a-z0-9][a-z0-9_-]*)\b/gi;
          const RUNNER_PROFILES = {
            linux: { runsOn: 'ubuntu-latest', os: 'linux' },
            windows: { runsOn: 'windows-latest', os: 'windows' },
            mac: { runsOn: 'macos-latest', os: 'macos' },
          };
          const RUN_ON_ALIASES = {
            linux: 'linux',
            ubuntu: 'linux',
            'ubuntu-latest': 'linux',
            windows: 'windows',
            win: 'windows',
            'windows-latest': 'windows',
            mac: 'mac',
            macos: 'mac',
            darwin: 'mac',
            'macos-latest': 'mac',
          };

          const username = context.payload.sender.login;
          let extraInstructions = '';
          let runnerProfile = 'linux';

          core.setOutput('should_run', 'false');
          core.setOutput('extra_instructions', '');
          core.setOutput('runs_on', JSON.stringify(RUNNER_PROFILES.linux.runsOn));
          core.setOutput('runner_os', RUNNER_PROFILES.linux.os);
          core.setOutput('runner_profile', runnerProfile);

          if (context.eventName === 'issues') {
            if (context.payload.action !== 'labeled' || context.payload.label?.name !== ANALYZE_LABEL) {
              console.log('Not a pi-analyze label event');
              return;
            }
          } else if (context.eventName === 'issue_comment') {
            if (context.payload.issue.pull_request) {
              console.log('Ignoring pull request comment');
              return;
            }
            const body = context.payload.comment.body || '';
            if (!TRIGGER_RE.test(body)) {
              console.log('Comment does not contain an @issuron analyze trigger');
              return;
            }

            const resolvedProfiles = new Set();
            const unknownTags = [];
            for (const match of body.matchAll(RUN_ON_TAG_RE)) {
              const tag = match[1].toLowerCase();
              const resolved = RUN_ON_ALIASES[tag];
              if (!resolved) {
                unknownTags.push(tag);
              } else {
                resolvedProfiles.add(resolved);
              }
            }

            if (unknownTags.length > 0) {
              core.setFailed(`Unknown issue analysis runner tag(s): ${unknownTags.map((tag) => `#run-on-${tag}`).join(', ')}`);
              return;
            }
            if (resolvedProfiles.size > 1) {
              core.setFailed(
                `Conflicting issue analysis runner tags: ${Array.from(resolvedProfiles)
                  .map((profile) => `#run-on-${profile}`)
                  .join(', ')}`,
              );
              return;
            }

            runnerProfile = Array.from(resolvedProfiles)[0] || 'linux';
            extraInstructions = body.replace(TRIGGER_RE, ' ').replace(RUN_ON_TAG_RE, ' ').trim();
          } else {
            console.log(`Unsupported event: ${context.eventName}`);
            return;
          }

          async function removeTriggerLabel() {
            if (context.eventName !== 'issues') return;
            try {
              await github.rest.issues.removeLabel({
                owner: context.repo.owner,
                repo: context.repo.repo,
                issue_number: context.issue.number,
                name: ANALYZE_LABEL,
              });
            } catch (error) {
              if (error.status !== 404) throw error;
            }
          }

          if (!process.env.ORG_READ_TOKEN) {
            await removeTriggerLabel();
            core.setFailed('EARENDIL_ORG_READ_TOKEN is not configured; refusing to run issue analysis.');
            return;
          }

          try {
            const response = await fetch(
              `https://api.github.com/orgs/earendil-works/teams/staff/memberships/${encodeURIComponent(username)}`,
              {
                headers: {
                  Accept: 'application/vnd.github+json',
                  Authorization: `Bearer ${process.env.ORG_READ_TOKEN}`,
                  'X-GitHub-Api-Version': '2022-11-28',
                },
              },
            );

            if (response.status === 404) {
              await removeTriggerLabel();
              core.setFailed(`@${username} is not an active earendil-works/staff member.`);
              return;
            }

            if (!response.ok) {
              const body = await response.text();
              await removeTriggerLabel();
              core.setFailed(
                `Could not verify earendil-works/staff membership for @${username}: HTTP ${response.status} ${body}`,
              );
              return;
            }

            const membership = await response.json();
            if (membership.state !== 'active') {
              await removeTriggerLabel();
              core.setFailed(`@${username} is not an active earendil-works/staff member.`);
              return;
            }
            console.log(`earendil-works/staff membership for @${username}: ${membership.state}`);
          } catch (error) {
            await removeTriggerLabel();
            core.setFailed(
              `Could not verify earendil-works/staff membership for @${username}: ${
                error instanceof Error ? error.message : String(error)
              }`,
            );
            return;
          }

          const { data } = await github.rest.repos.getCollaboratorPermissionLevel({
            owner: context.repo.owner,
            repo: context.repo.repo,
            username,
          });
          if (!['admin', 'write'].includes(data.permission)) {
            await removeTriggerLabel();
            core.setFailed(
              `@${username} has '${data.permission}' permission; write or admin is required to trigger issue analysis.`,
            );
            return;
          }

          if (context.eventName === 'issue_comment') {
            await github.rest.issues.addLabels({
              owner: context.repo.owner,
              repo: context.repo.repo,
              issue_number: context.issue.number,
              labels: [ANALYZE_LABEL],
            });
          }

          const profile = RUNNER_PROFILES[runnerProfile];
          console.log(`Selected issue analysis runner profile: ${runnerProfile} (${JSON.stringify(profile.runsOn)})`);
          core.setOutput('should_run', 'true');
          core.setOutput('extra_instructions', extraInstructions);
          core.setOutput('runs_on', JSON.stringify(profile.runsOn));
          core.setOutput('runner_os', profile.os);
          core.setOutput('runner_profile', runnerProfile);

